import React from "react";

const JobCard = ({ job, onLike }) => {
  // Function to handle sharing
  const handleShare = () => {
    const jobURL = window.location.href; // Replace with actual job URL

    if (navigator.share) {
      navigator
        .share({
          title: job.title,
          text: `Check out this job: ${job.title} - ${job.description}`,
          url: jobURL,
        })
        .then(() => console.log("Job shared successfully!"))
        .catch((error) => console.error("Error sharing job:", error));
    } else {
      // Open social media sharing links in a new tab
      const twitterURL = `https://twitter.com/intent/tweet?text=${encodeURIComponent(
        job.title
      )}&url=${encodeURIComponent(jobURL)}`;
      const whatsappURL = `https://wa.me/?text=${encodeURIComponent(
        job.title + " - " + jobURL
      )}`;
      const linkedinURL = `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(
        jobURL
      )}`;
      const emailURL = `mailto:?subject=${encodeURIComponent(
        "Check out this job!"
      )}&body=${encodeURIComponent(job.title + "\n" + jobURL)}`;

      window.open(
        twitterURL,
        "_blank"
      ); /* Open Twitter (replace with other social media links as needed) */
    }
  };


  return (
    <div className="job-card">
      {/* Display image if available */}
      {job.fileAttachment && (
        <img src={job.fileAttachment} alt={job.title} className="job-image" />
      )}

      <div className="job-content">
        <h3>{job.title}</h3>
        <p>{job.description}</p>

        <div className="skills-tags">
          {job.skillsRequired.map((skill, index) => (
            <span key={index}>{skill}</span>
          ))}
        </div>

        <div className="job-meta">
          <span>💰 ${job.budget}</span>
          <span>⏳ {job.timeline}</span>
          <span>❤️ {job.likes} Likes</span>
        </div>

        <div className="engagement-buttons">
          <button className="like-btn" onClick={() => onLike(job._id)}>
            ❤️ Like
          </button>
          <button className="bookmark-btn">📌</button>
          <button className="share-btn" onClick={handleShare}>
            📤 Share
          </button>
        </div>

        <button className="apply-btn">Apply Now</button>
      </div>
    </div>
  );
};

export default JobCard;
